// CSD_RATIONALE_BEGIN
// Root causes of prior failures (10.2% accuracy, 41/44 wrong answers):
//
// 1. EARLY SPAN ENTRY: The model writes `<<` after ~41 tokens on an
//    intermediate value (e.g., <<n1 + n2>>), then degenerates into "!!!!"
//    because the constrained parser admits pathological tokens after a
//    complete expression.
//
// 2. SEMANTIC MISMATCH: When the constrained span captures an intermediate
//    value, the evaluator's "last visible span" extractor uses that wrong
//    intermediate answer instead of the final answer.
//
// 3. DEAD-END DEGENERATION: After a constrained span closes (or reaches a
//    dead end), the strategy had no graceful re-entry, causing the
//    "!!!!!!!!!" fill pattern.
//
// Fix:
//   Phase 1 — Generate freeLimit = maxSteps-120 tokens of FULLY unconstrained
//   text WITHOUT entering constrained mode, even when "<<" appears.  The
//   model's intermediate "<<n1+n2>>" spans become harmless free text because
//   the evaluator uses the LAST closed visible span.
//
//   Phase 2 — Short UnconstrainedChunk window (≤20 steps) to detect a
//   naturally-emitted final "<<".
//
//   Phase 3 — Force OpenConstrainedSpan if still outside a span.
//
//   Phase 4 — CloseSpanWithinBudget on the remaining budget to dead-end-
//   aware generate and close the FINAL correct answer span.
//
// Because the evaluator extracts from the LAST "<<...>>" span, forced
// constrained content near the end overrides any wrong intermediate spans.
//
// Guidance targets the "n - frac*n" vs "n - int(n*frac)" class of semantic
// errors by explicitly instructing use of int() and //.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 loop: insideConstrainedOut is never assigned in the loop body,
//   so it retains its entry value.  When insideConstrained=false on entry,
//   insideConstrainedOut stays false and the implication is vacuously true.
//   When insideConstrained=true on entry, the loop guard (!insideConstrainedOut)
//   immediately fails and the loop body never runs; the implication holds from
//   the method precondition.
//
//   Phase 2 (UnconstrainedChunk): If sOpen=true we set
//   currentConstrainedOut := [].  parser.IsValidPrefix([]) holds by the method
//   precondition.  If sOpen=false, state is unchanged from Phase 1.
//
//   Phase 3 (OpenConstrainedSpan): Sets insideConstrainedOut=true,
//   currentConstrainedOut=[] which is parser-valid by precondition.
//
//   Phase 4 (CloseSpanWithinBudget): Its postcondition directly guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
//   Phase 1 loop: Each iteration increments steps by 1 before any append.
//   EOS breaks without appending; non-EOS appends exactly one token.
//   Both cases preserve |generated| <= |generatedPrefix| + steps.
//
//   Phase 2 (UnconstrainedChunk): sUsed <= smallBudget <= maxSteps - steps_before.
//   Helper postcondition: |gO| <= |generated_before| + sUsed.
//   steps := steps + sUsed, so the bound is preserved.
//
//   Phase 3 (OpenConstrainedSpan): appends exactly one token ("<<"), steps += 1.
//   Bound preserved.
//
//   Phase 4 (CloseSpanWithinBudget): appends at most remainBudget visible
//   tokens (its postcondition: |cg| <= |generated_before| + remainBudget).
//   steps := steps + remainBudget = maxSteps.  Final bound:
//   |generated| <= |generatedPrefix| + maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step using the exact variable names from the problem. Complete ALL your reasoning first. Then write ONLY the final Python expression in << >> at the very end. Use int() to convert fractions to integers (e.g., int(n * frac)), and // for integer division. Never open << >> for intermediate steps.");

var steps: nat := 0;
var freeLimit: nat := if maxSteps > 120 then maxSteps - 120 else 0;

// Phase 1: Extended free-text reasoning — do NOT enter constrained mode
while steps < freeLimit && steps < maxSteps && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  // Deliberately do NOT detect "<<" here — let intermediate spans flow as free text
}

// Phase 2: Short free window to catch a naturally-emitted final "<<"
if steps < maxSteps && !insideConstrainedOut {
  var smallBudget: nat := if maxSteps - steps >= 20 then 20 else maxSteps - steps;
  var gO, sOpen, sEos, sUsed := helpers.UnconstrainedChunk(lm, prompt, generated, smallBudget, "<<", eosToken);
  generated := gO;
  steps := steps + sUsed;
  if sOpen {
    insideConstrainedOut := true;
    currentConstrainedOut := [];
  }
}

// Phase 3: Force open a constrained span if still outside one
if steps < maxSteps && !insideConstrainedOut {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 4: Dead-end-aware constrained generation + graceful close
if insideConstrainedOut && steps < maxSteps {
  var remainBudget: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainBudget);
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + remainBudget;
}

cost := steps;

